.intro-description{font-size:16px;line-height:1.8;margin-top:24px}
.catalog-meta{display:inline-flex;flex-wrap:wrap;gap:5px;background:var(--mint);border:1px solid #d2dec7;border-radius:100px;padding:6px 12px;font-size:11px}
.how-to{background:#173e30;border-color:#284e39;border-radius:12px;padding:28px 29px;color:#eef4e4;box-shadow:0 12px 25px #173e300c}
.how-to h2{font:400 28px/1.2 Georgia,serif;letter-spacing:-.02em;margin-bottom:21px}
