.how-to li{margin-bottom:14px}
.how-to li::marker{color:var(--lime)}
.how-to strong{color:#fffef9}
.learner-link{background:var(--lime);color:#173e30;text-decoration:none;border-radius:6px;padding:10px 14px;min-height:44px}
.learner-link:hover{background:#e6f0c6}
.how-to-note{font-size:11px;line-height:1.65;color:#bdd1b0;margin-top:16px}
.course-section{padding-top:34px}
.section-heading{align-items:center;background:#eaf0e4;border:1px solid #cdd9c5;padding:20px 22px;border-radius:9px}
