.section-heading .eyebrow{font-size:10px}
.search-field input{min-height:46px;border-color:#a1b398;border-radius:6px}
.search-field label{font-size:11px;color:#405d3b}
.course-grid{gap:18px}
.course-card{border-radius:9px;padding:25px;box-shadow:none}
.course-card:focus-within{border-color:#7d9e6c}
.course-title{font-size:27px;line-height:1.2}
.course-count{font-size:10px;color:#546f47}
.course-concepts li{background:#eef3e7;border-color:#d8e2cf;color:#4b633f;border-radius:100px;font-size:10px}
.course-detail summary{min-height:44px}
.download-button{background:#173e30;border-color:#173e30;min-height:46px;border-radius:6px;padding-inline:18px;font-size:12px}
.download-button:hover{background:var(--green)}
.catalog-footer{margin-top:10px}
.catalog-footer p a{margin-top:0}
